// Writes src/lib/specIndex.ts: one import per JSON file in python/loopbricks/spec, so adding a spec needs no edits.
import { readdirSync, writeFileSync } from "node:fs";
const files = readdirSync("python/loopbricks/spec").filter((f) => f.endsWith(".json")).sort();
const id = (f) => "s_" + f.slice(0, -5).replace(/[^A-Za-z0-9]/g, "_");
writeFileSync(
  "src/lib/specIndex.ts",
  "// Generated by `npm run specs` from python/loopbricks/spec/*.json. Do not edit.\n" +
    files.map((f) => `import ${id(f)} from "../../python/loopbricks/spec/${f}";`).join("\n") +
    `\n\nexport const SPEC_FILES: unknown[] = [${files.map(id).join(", ")}];\n`
);
console.log(`indexed ${files.length} specs`);
